package com.kuzhi.findme.server.vehicle;

import java.util.Set;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntityType;

public record VehicleRescueProfile(MotionType motionType, double approachSpeed, double maxStepUp, double maxStepDown, int brakeTicks) {
    private static final Set<String> SUPERB_AIRCRAFT = Set.of("a_10a", "ac_130h", "ah_6", "j_16", "ju_87", "mi_28", "kirov", "air_sheep", "happiest_ghast", "annihilator");

    public static VehicleRescueProfile forEntity(Entity entity) {
        return VehicleRescueProfile.forId(EntityType.m_20613_((EntityType)entity.m_6095_()));
    }

    static VehicleRescueProfile forId(ResourceLocation id) {
        String path;
        String namespace = id == null ? "minecraft" : id.m_135827_();
        String string = path = id == null ? "" : id.m_135815_();
        MotionType type = "minecraft".equals(namespace) && path.contains("minecart") ? MotionType.GROUND : ("immersive_aircraft".equals(namespace) ? ("warship".equals(path) ? MotionType.WATER : MotionType.AIR) : ("superbwarfare".equals(namespace) ? (path.equals("speedboat") || path.equals("tiny_speedboat") ? MotionType.WATER : (SUPERB_AIRCRAFT.contains(path) ? MotionType.AIR : MotionType.GROUND)) : (VehicleRescueProfile.containsAny(path, "boat", "ship", "submarine", "raft") ? MotionType.WATER : (VehicleRescueProfile.containsAny(path, "plane", "aircraft", "helicopter", "jet", "airship") ? MotionType.AIR : MotionType.GROUND))));
        return switch (type) {
            default -> throw new IncompatibleClassChangeError();
            case MotionType.GROUND -> new VehicleRescueProfile(type, 0.78, 1.15, 1.35, 18);
            case MotionType.AIR -> new VehicleRescueProfile(type, 1.05, 1.8, 1.8, 14);
            case MotionType.WATER -> new VehicleRescueProfile(type, 0.72, 0.65, 0.65, 20);
        };
    }

    private static boolean containsAny(String value, String ... needles) {
        for (String needle : needles) {
            if (!value.contains(needle)) continue;
            return true;
        }
        return false;
    }

    public static enum MotionType {
        GROUND,
        AIR,
        WATER;

    }
}

